function lowerFirst(value: string) {
  return value ? value.charAt(0).toLocaleLowerCase('es') + value.slice(1) : value;
}

function fallbackSteps(input: TechniqueEditorialInput): string[] {
  const objective = lowerFirst((input.objective || input.definition).replace(/[.]$/,''));
  const family = input.family;
  if (family === 'Preparación y corte') {
    return [
      'Prepara una tabla estable, el utensilio adecuado y el ingrediente limpio y seco.',
      'Ejecuta ' + input.title.toLocaleLowerCase('es') + ' con cortes o movimientos controlados para ' + objective + '.',
      'Mantén tamaño, forma y presión uniformes y corrige las piezas irregulares antes de seguir.',
      'Revisa el resultado y conserva o cocina de inmediato cuando el ingrediente pueda oxidarse o perder textura.'
    ];
  }
  if (family === 'Preelaboración y conservación') {
    return [
      'Pesa y prepara todos los componentes y utiliza recipientes limpios adecuados al proceso.',
      'Aplica el medio de tratamiento de forma uniforme para ' + objective + '.',
      'Controla tiempo, temperatura, proporciones y cobertura durante todo el proceso.',
      'Finaliza, enfría o conserva exactamente como indique la receta o procedimiento específico.'
    ];
  }
  return [
    'Prepara producto, utensilios y fuente de calor antes de empezar.',
    'Aplica la técnica de forma progresiva para ' + objective + '.',
    'Controla el punto real del alimento y el parámetro crítico indicado, ajustando intensidad si es necesario.',
    'Detén la técnica en cuanto aparezcan las señales de éxito y continúa con la siguiente fase de la receta.'
  ];
}

function defaultIngredients(input: TechniqueEditorialInput): string[] {
  if (input.commonIngredients?.length) return input.commonIngredients;
  const title = input.title;
  if (input.family === 'Preparación y corte') return ['Ingrediente que se va a ' + title.toLocaleLowerCase('es')];
  if (input.family === 'Agua, vapor y presión') return ['Alimento indicado por la receta', 'Agua, caldo u otro líquido de cocción cuando corresponda'];
  if (input.family === 'Sartén y fritura') return ['Alimento indicado por la receta', 'Grasa de cocción adecuada cuando corresponda'];
  if (input.family === 'Horno, fuego y guisos') return ['Ingrediente o pieza principal', 'Grasa, líquido o aromáticos según la receta'];
  if (input.family === 'Salsas y fondos') return ['Base líquida o grasa de la elaboración', 'Aromáticos y agentes de ligazón según la técnica'];
  if (input.family === 'Huevos, arroces y pasta') return ['Ingrediente principal de la técnica', 'Agua, caldo, grasa o condimentos según la receta'];
  if (input.family === 'Carnes, pescados y mariscos') return ['Pieza de carne, pescado o marisco indicada', 'Condimentos o medio de cocción según la receta'];
  if (input.family === 'Panadería, pastelería y heladería') return ['Masa, crema, chocolate o base indicada por la receta'];
  if (input.family === 'Alta cocina y emplatado') return ['Preparación base definida por una fórmula o receta compatible'];
  return ['Ingrediente o preparación sobre la que se aplicará la técnica'];
}

function miseEnPlace(input: TechniqueEditorialInput, steps: string[]): string[] {
  const items: string[] = [];
  if (input.equipment?.length) items.push('Prepara: ' + input.equipment.join(' · ') + '.');
  if (input.requiresValidatedRecipe) items.push('Ten a la vista la receta validada con sus parámetros de tiempo, temperatura o proporción.');
  const first = steps[0];
  if (first && !items.some(item => item.includes(first))) items.push(first);
  if (!items.length) items.push('Organiza el puesto de trabajo y deja a mano todo lo necesario antes de empezar.');
  return items;
}

export function buildTechniqueEditorial(input: TechniqueEditorialInput): TechniqueEditorial {
  const steps = SPECIFIC_STEPS[input.title] || (CUT_SHAPES[input.title]
    ? [
        'Prepara el ingrediente limpio, una tabla estable y un cuchillo bien afilado.',
        'Regulariza la pieza si hace falta y crea primero caras, láminas o bastones de referencia.',
        'Corta ' + CUT_SHAPES[input.title] + ' manteniendo grosor y longitud constantes.',
        'Separa las piezas irregulares para otro uso y conserva juntas las de tamaño similar para una cocción uniforme.'
      ]
    : fallbackSteps(input));

  const point = (input.pointKey || 'controlar el punto real del alimento').replace(/[.]$/,'');
  const objective = lowerFirst((input.objective || input.definition).replace(/[.]$/,''));

  return {
    ingredients: defaultIngredients(input),
    miseEnPlace: miseEnPlace(input, steps),
    steps,
    whenToUse: 'Úsala cuando necesites ' + objective + '.',
    whenNotToUse: input.requiresValidatedRecipe
      ? 'No la improvises sin una receta o procedimiento que fije los parámetros críticos para el producto concreto.'
      : 'Elige otra técnica cuando el resultado buscado requiera un efecto distinto o no puedas ' + point.toLocaleLowerCase('es') + '.',
    chefTip: 'Clave práctica: ' + point + '.'
  };
}
